// Auto-generated catalog of all available isometric assets
// Asset names correspond to files in /public/assets/{theme}/{Category}/{name}.png

export type MapTheme = "city" | "dungeon"

export type AssetCategory = "grounds" | "buildings" | "props" | "vehicles"

export interface AssetEntry {
  name: string
  category: AssetCategory
  path: string
}

// ============================================================
// City assets – paths under /assets/city/{Category}/
// ============================================================
const G = (name: string): AssetEntry => ({
  name,
  category: "grounds",
  path: `/assets/city/Grounds/${name}.png`,
})
const B = (name: string): AssetEntry => ({
  name,
  category: "buildings",
  path: `/assets/city/Buildings/${name}.png`,
})
const P = (name: string): AssetEntry => ({
  name,
  category: "props",
  path: `/assets/city/Props/${name}.png`,
})
const V = (name: string): AssetEntry => ({
  name,
  category: "vehicles",
  path: `/assets/city/Vehicles/${name}.png`,
})

